from pathlib import Path
import pandas as pd,numpy as np,json,datetime
P=Path(__file__).resolve().parents[1];O=P/'outputs';BASE=P.parents[2]
f=pd.read_parquet(O/'monthly-panel.parquet');s=pd.read_parquet(O/'signals.parquet');a=pd.read_parquet(O/'group-assignments.parquet');master=pd.read_csv(BASE/'quant-research-library/diagnostics/20261102-price-volume-quality-v1/dataset/universe-frozen.csv');master['delist_date']=pd.to_datetime(master.delist_date,errors='coerce');de=master.set_index('symbol').delist_date
s=s.merge(a[['candidate','target_month','instrument','group']],on=['candidate','target_month','instrument'],how='left',validate='one_to_one');assert s['group'].notna().all();cal=pd.DatetimeIndex(pd.to_datetime((O/'calendar.txt').read_text().splitlines()));ends=pd.Series(cal,index=cal.to_period('M')).groupby(level=0).max();nexts={m:(cal[cal>day].min() if (cal>day).any() else pd.NaT) for m,day in ends.items()};rows=[]
for label in ['label_close','label_open']:
 q=s.copy();q['exit_date']=pd.PeriodIndex(q.target_month,freq='M').map(ends if label=='label_close' else nexts);q['delist_date']=q.instrument.map(de);q['missing']=q[label].isna();q['mature']=q.close_mature if label=='label_close' else q.open_mature;q['known_terminal_before_exit']=q.missing & q.mature & q.delist_date.notna() & (q.delist_date<=q.exit_date);q['mature_unresolved_missing']=q.missing & q.mature & ~q.known_terminal_before_exit;q['immature']=~q.mature
 counts=q.groupby(['candidate','target_month','group']).agg(intended=('instrument','size'),missing=('missing','sum'),known_terminal_before_exit=('known_terminal_before_exit','sum'),mature_unresolved_missing=('mature_unresolved_missing','sum'),immature=('immature','sum')).reset_index();counts['label']=label;assert (counts.missing==counts.known_terminal_before_exit+counts.mature_unresolved_missing+counts.immature).all();rows.append(counts)
pd.concat(rows).to_csv(O/'missing-outcome-classification.csv',index=False)
c=f.groupby('formation_month').agg(source_rows=('instrument','size'),amplitude_eligible=('amplitude_current_eligible','sum'),amplitude_available=('ideal_amplitude20','count'),ovnt_available=('ovnt12','count'),overnight_complete_months=('overnight_month','count'),monthly_return_available=('month_return','count')).reset_index();c.to_csv(O/'monthly-source-coverage.csv',index=False)
summary={'at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'classification_posthoc_diagnostic_only':True,'not_used_to_drop_or_reweight_any_candidate':'No results changed','known_terminal_definition':'Official delist date <= planned exit; classification not observed terminal liquidation return','unresolved_missing_includes':'Unknown suspension/source gaps/quality mask; not automatically classified tradeable','counts':pd.concat(rows).groupby(['candidate','label'])[['intended','missing','known_terminal_before_exit','mature_unresolved_missing','immature']].sum().reset_index().to_dict('records'),'first_month_missing_return_count':int(f.loc[f.formation_month.eq('2019-01'),'month_return'].isna().sum()),'first_month_rows':int(f.formation_month.eq('2019-01').sum()),'first_month_overnight_missing_count':int(f.loc[f.formation_month.eq('2019-01'),'overnight_month'].isna().sum())}
(O/'coverage-audit-summary.json').write_text(json.dumps(summary,indent=2));print(json.dumps(summary,indent=2))
